/**
 * Custom Worker entry: OpenNext's Next.js handler for requests, plus a
 * scheduled handler for the 15-minute cron (cost checks, live-broadcast safety
 * net). The cron calls an internal route so the logic stays in the app.
 */
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,

  async scheduled(_event: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    // Straight into the app's own handler: no network hop, works the same locally.
    const request = new Request(new URL("/api/internal/cron", env.APP_URL), {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      Promise.resolve(handler.fetch(request, env, ctx)).then(async (response: Response) => {
        if (!response.ok) console.error("Cron run failed", response.status, await response.text());
        else console.log("Cron run", await response.text());
      }),
    );
  },
} satisfies ExportedHandler<CloudflareEnv>;

// OpenNext's Durable Object classes, if a cache override ever needs them.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
export * from "./.open-next/worker.js";
